import { sendRequest } from '../bridge/bridge';

export type ConfirmOptions = {
    title?: string;
    message: string;
    textButtonApply?: string;
    textButtonCancel?: string;
    theme?: 'normal' | 'danger';
};

export type ConfirmResult = { confirmed: boolean };

const CONFIRM_TIMEOUT_MS = 300_000;

export class Confirm {
    show(options: ConfirmOptions): Promise<ConfirmResult> {
        return sendRequest('confirm.show', options, {
            timeout: CONFIRM_TIMEOUT_MS,
        }) as Promise<ConfirmResult>;
    }
}
