import type { ExternalApiDomainInfo } from './ExternalApiDomainInfo';
import type { GenericSchema } from 'valibot';
import { object, optional, string, union } from 'valibot';

const localizedStringSchema: GenericSchema<
    | string
    | {
          en?: string;
          ru?: string;
      }
> = union([
    string(),
    object({
        en: optional(string()),
        ru: optional(string()),
    }),
]);

export const externalApiDomainInfoSchema: GenericSchema<ExternalApiDomainInfo> = object({
    domain: string(),
    instructions: optional(localizedStringSchema),
});
