/**
 * Структурный shape `LocalizedString` — общая база, к которой структурно
 * совместимы api-types `LocalizedString` обоих flavors. Реальная функция
 * `getLocalizedString` читает только ключи `ru` и `en`, поэтому более
 * узкие api-types-варианты (с дополнительными ключами) совместимы.
 */
export type LocalizedString = string | { ru?: string; en?: string };

/**
 * Получить локализованную строку на основе языка
 * @param value - Локализованная строка
 * @param language - Код языка ('ru' или 'en')
 * @param fallbackLanguage - Резервный язык (по умолчанию 'ru')
 */
export function getLocalizedString(
    value: LocalizedString,
    language: string | undefined,
    fallbackLanguage = 'ru',
): string {
    if (typeof value === 'string') {
        return value;
    }

    const lang = (language ?? fallbackLanguage).toLowerCase() as 'ru' | 'en';
    const fallback = fallbackLanguage.toLowerCase() as 'ru' | 'en';

    return value[lang] || value[fallback] || value.ru || value.en || '';
}
