export type ResizeCallback = (height: number) => Promise<void> | void;

export class AutoResizeManager {
    private resizeCallback: ResizeCallback;
    private resizeObserver?: ResizeObserver;
    private resizeTimeout?: ReturnType<typeof setTimeout>;
    private lastHeight = 0;
    private isUpdating = false;
    private consecutiveSmallIncreases = 0;
    private readonly MAX_CONSECUTIVE_SMALL_INCREASES = 5;
    private readonly SMALL_INCREASE_THRESHOLD_PX = 10;

    constructor(resizeCallback: ResizeCallback) {
        this.resizeCallback = resizeCallback;
    }

    enable(): void {
        if (!document.body) {
            console.error('[AutoResize] document.body does not exist yet');
            return;
        }

        const sendHeight = async () => {
            if (this.isUpdating) {
                return;
            }

            // Use body.scrollHeight as primary source in iframe
            // documentElement.scrollHeight can cache old values
            const root = document.getElementById('root');
            const bodyStyles = window.getComputedStyle(document.body);
            const marginTop = parseInt(bodyStyles.marginTop, 10) || 0;
            const marginBottom = parseInt(bodyStyles.marginBottom, 10) || 0;

            const measuredHeight = Math.max(
                document.body.scrollHeight,
                document.body.offsetHeight,
                root ? root.scrollHeight + marginTop + marginBottom : 0,
            );

            // Add small buffer to compensate for rounding errors
            const height = measuredHeight + 4;

            if (height !== this.lastHeight) {
                // Detect infinite loop: if height keeps increasing by small amounts
                // This prevents issues with elements using viewport units (vh, %)
                if (height > this.lastHeight) {
                    const increase = height - this.lastHeight;

                    // Only count small increases as potential loop indicators
                    // Large increases are normal (user adding content)
                    if (increase <= this.SMALL_INCREASE_THRESHOLD_PX) {
                        this.consecutiveSmallIncreases++;

                        if (this.consecutiveSmallIncreases > this.MAX_CONSECUTIVE_SMALL_INCREASES) {
                            console.warn(
                                '[AutoResize] Infinite loop detected. Stopping auto-resize. ' +
                                    'This may be caused by elements with viewport-relative units (vh, %).',
                            );
                            this.disable();
                            return;
                        }
                    } else {
                        // Large increase - reset counter (normal content addition)
                        this.consecutiveSmallIncreases = 0;
                    }
                } else {
                    // Height decreased - reset counter
                    this.consecutiveSmallIncreases = 0;
                }

                this.isUpdating = true;
                this.lastHeight = height;

                try {
                    await this.resizeCallback(height);
                } catch (error) {
                    console.error('[AutoResize] Failed to update content size:', error);
                } finally {
                    this.isUpdating = false;
                }
            }
        };

        const debouncedSendHeight = () => {
            clearTimeout(this.resizeTimeout);
            this.resizeTimeout = setTimeout(sendHeight, 100);
        };

        this.resizeObserver = new ResizeObserver(debouncedSendHeight);
        this.resizeObserver.observe(document.body);

        // Send initial height
        sendHeight();
    }

    disable(): void {
        this.resizeObserver?.disconnect();
        clearTimeout(this.resizeTimeout);
        this.isUpdating = false;
        this.consecutiveSmallIncreases = 0;
    }
}
