import { sendRequest } from '../bridge/bridge';
import type { NavigateRequest } from '../host/types/NavigateRequest';
import { Confirm } from './Confirm';
import { Toaster } from './Toaster';

class UiApi {
    readonly toaster = new Toaster();
    readonly confirm = new Confirm();

    navigate(payload: NavigateRequest): Promise<unknown> {
        return sendRequest('navigate', payload);
    }
}

export const uiApi = new UiApi();
