import type { RuntimeParams } from './types/RuntimeParams';

function parseJsonParam<T>(value: string | null, fallback: T): T {
    if (!value) {
        return fallback;
    }

    return JSON.parse(value) as T;
}

function parseQueryParams(value: string | null): Record<string, string> {
    if (!value) {
        return {};
    }

    return JSON.parse(decodeURIComponent(value)) as Record<string, string>;
}

export function readRuntimeParams(search = location.search): RuntimeParams {
    const searchParams = new URLSearchParams(search);
    const service = searchParams.get('service');
    const slot = searchParams.get('slot');
    const parentOrigin = searchParams.get('parentOrigin');
    const pluginId = searchParams.get('id');
    const elementId = searchParams.get('elementId');

    if (!service) {
        throw new Error(
            'Missing required URL parameter "service". A plugin cannot run outside the host application context. ' +
                'Open the plugin from the host application.',
        );
    }

    if (!slot) {
        throw new Error('Slot is not defined');
    }

    if (!parentOrigin) {
        throw new Error('Target origin is not defined');
    }

    if (!pluginId) {
        throw new Error('Plugin id is not defined');
    }

    if (!elementId) {
        throw new Error('Element id is not defined');
    }

    const contextLevelParam = searchParams.get('contextLevel');

    return {
        service,
        slot,
        parentOrigin,
        pluginId,
        elementId,
        entityId: searchParams.get('entityId'),
        entityMeta: parseJsonParam<Record<string, string> | undefined>(
            searchParams.get('entityMeta'),
            undefined,
        ),
        contextLevel: contextLevelParam === 'basic' ? 'basic' : 'full',
        innerUrl: searchParams.get('innerUrl') ?? '',
        queryParams: parseQueryParams(searchParams.get('queryParams')),
    };
}
