import { number, object, optional, record, string, unknown } from 'valibot';

import { authContextTypeSchema } from '../constants/authContextTypeSchema';
import { pluginProxyMethodSchema } from '../constants/pluginProxyMethodSchema';

export const externalApiCallPayloadSchema = object({
    url: string(),
    method: pluginProxyMethodSchema,
    headers: optional(record(string(), string())),
    body: optional(record(string(), unknown())),
    timeoutMs: optional(number()),
    contextType: optional(authContextTypeSchema),
});
