import { destroyBridge, initBridge, sendRequest } from '../bridge/bridge';
import { readRuntimeParams } from './readRuntimeParams';
import type { BaseHostContract } from './types/BaseHostContract';
import type { ContentSizeUpdateRequest } from './types/ContentSizeUpdateRequest';
import type { ExternalApiAuthCheckAndRequestPayload } from './types/ExternalApiAuthCheckAndRequestPayload';
import type { ExternalApiAuthGetStatusPayload } from './types/ExternalApiAuthGetStatusPayload';
import type { ExternalApiAuthRequestPayload } from './types/ExternalApiAuthRequestPayload';
import type { ExternalApiAuthRevokePayload } from './types/ExternalApiAuthRevokePayload';
import type { ExternalApiCallPayload } from './types/ExternalApiCallPayload';
import type { NavigateRequest } from './types/NavigateRequest';
import type { RuntimeParams } from './types/RuntimeParams';
import { AutoResizeManager } from './utils/autoResize';

/** Shorthand: extract the result type for a given method key from BaseHostContract */
type HostResult<K extends keyof BaseHostContract> = BaseHostContract[K]['result'];

export interface HostInitOptions {
    /**
     * Автоматически изменять размер контейнера плагина
     * при изменении содержимого
     * @default true
     */
    autoResize?: boolean;
}

/**
 * Untyped runtime класс HostApi. Methods, которые возвращают значения,
 * зависящие от SlotContextMap, типизированы как `unknown` или `string`.
 * Type-safety добавляется в публикуемых пакетах через typed wrapper.
 */
export type ContextLevel = 'basic' | 'full';

export type BasicContext = {
    entityId: string;
    entityMeta?: Record<string, string>;
};

export class HostApi<TContext = unknown> {
    private autoResizeManager?: AutoResizeManager;
    private slot: string | null = null;
    private service: string | null = null;
    private origin: string | null = null;
    private innerUrl: string | null = null;
    private queryParams: Record<string, string> | null = null;
    private entityId: string | null = null;
    private entityMeta: Record<string, string> | undefined = undefined;
    private contextLevel: ContextLevel = 'full';

    getTheme(): Promise<HostResult<'theme.get'>> {
        return sendRequest<HostResult<'theme.get'>>('theme.get');
    }

    getLanguage(): Promise<HostResult<'language.get'>> {
        return sendRequest<HostResult<'language.get'>>('language.get');
    }

    getUserId(): Promise<HostResult<'userId.get'>> {
        return sendRequest<HostResult<'userId.get'>>('userId.get');
    }

    getOrgId(): Promise<HostResult<'orgId.get'>> {
        return sendRequest<HostResult<'orgId.get'>>('orgId.get');
    }

    getIsYateam(): Promise<HostResult<'isYateam.get'>> {
        return sendRequest<HostResult<'isYateam.get'>>('isYateam.get');
    }

    getIsOrbita(): Promise<HostResult<'isOrbita.get'>> {
        return sendRequest<HostResult<'isOrbita.get'>>('isOrbita.get');
    }

    getContext(): Promise<TContext> {
        return sendRequest<TContext>('context.get');
    }

    updateContentSize(
        payload: ContentSizeUpdateRequest,
    ): Promise<HostResult<'contentSize.update'>> {
        return sendRequest<HostResult<'contentSize.update'>>('contentSize.update', payload);
    }

    notifyReady(): Promise<HostResult<'plugin.ready'>> {
        return sendRequest<HostResult<'plugin.ready'>>('plugin.ready');
    }

    close(
        payload: BaseHostContract['plugin.close']['payload'],
    ): Promise<HostResult<'plugin.close'>> {
        return sendRequest<HostResult<'plugin.close'>>('plugin.close', payload);
    }

    preventClose(
        payload: BaseHostContract['plugin.preventClose']['payload'],
    ): Promise<HostResult<'plugin.preventClose'>> {
        return sendRequest<HostResult<'plugin.preventClose'>>('plugin.preventClose', payload);
    }

    navigate(payload: NavigateRequest): Promise<unknown> {
        return sendRequest('navigate', payload);
    }

    init(options: HostInitOptions): void {
        const { autoResize = true } = options;
        const runtimeParams = readRuntimeParams();

        initBridge(
            runtimeParams.pluginId,
            runtimeParams.elementId,
            runtimeParams.slot,
            runtimeParams.entityId,
            runtimeParams.parentOrigin,
            runtimeParams.entityMeta,
        );

        this.applyRuntimeParams(runtimeParams);

        if (autoResize) {
            this.autoResizeManager = new AutoResizeManager(
                (height) => this.updateContentSize({ height }) as unknown as Promise<void>,
            );
            this.autoResizeManager.enable();
        }
    }

    getSlot(): string {
        if (this.slot === null) {
            throw new Error('Plugin not initialized. Call init() first.');
        }
        return this.slot;
    }

    getService(): string {
        if (this.service === null) {
            throw new Error('Service not initialized. Call init() first.');
        }
        return this.service;
    }

    getOrigin(): string {
        if (this.origin === null) {
            throw new Error('Origin not initialized. Call init() first.');
        }
        return this.origin;
    }

    getInnerUrl(): string {
        if (this.innerUrl === null) {
            throw new Error('Plugin not initialized. Call init() first.');
        }
        return this.innerUrl;
    }

    getQueryParams(): Record<string, string> {
        if (this.queryParams === null) {
            throw new Error('Plugin not initialized. Call init() first.');
        }
        return this.queryParams;
    }

    getEntityId(): string | null {
        return this.entityId;
    }

    getEntityMeta(): Record<string, string> | undefined {
        return this.entityMeta;
    }

    getContextLevel(): ContextLevel {
        return this.contextLevel;
    }

    disableAutoResize(): void {
        this.autoResizeManager?.disable();
    }

    destroy(): void {
        this.autoResizeManager?.disable();
        this.autoResizeManager = undefined;
        destroyBridge();
        this.slot = null;
        this.service = null;
        this.origin = null;
        this.innerUrl = null;
        this.queryParams = null;
        this.entityId = null;
        this.entityMeta = undefined;
        this.contextLevel = 'full';
    }

    externalApiAuthGetStatus(
        payload: ExternalApiAuthGetStatusPayload,
    ): Promise<HostResult<'externalApi.auth.getStatus'>> {
        return sendRequest<HostResult<'externalApi.auth.getStatus'>>(
            'externalApi.auth.getStatus',
            payload,
        );
    }

    externalApiAuthRevoke(
        payload: ExternalApiAuthRevokePayload,
    ): Promise<HostResult<'externalApi.auth.revoke'>> {
        return sendRequest<HostResult<'externalApi.auth.revoke'>>(
            'externalApi.auth.revoke',
            payload,
        );
    }

    externalApiAuthRequest(
        payload: ExternalApiAuthRequestPayload,
    ): Promise<HostResult<'externalApi.auth.request'>> {
        return sendRequest<HostResult<'externalApi.auth.request'>>(
            'externalApi.auth.request',
            payload,
        );
    }

    externalApiAuthCheckAndRequest(
        payload: ExternalApiAuthCheckAndRequestPayload,
    ): Promise<HostResult<'externalApi.auth.checkAndRequest'>> {
        return sendRequest<HostResult<'externalApi.auth.checkAndRequest'>>(
            'externalApi.auth.checkAndRequest',
            payload,
        );
    }

    externalApiCall(payload: ExternalApiCallPayload): Promise<HostResult<'externalApi.call'>> {
        return sendRequest<HostResult<'externalApi.call'>>('externalApi.call', payload);
    }

    private applyRuntimeParams(runtimeParams: RuntimeParams): void {
        this.service = runtimeParams.service;
        this.slot = runtimeParams.slot;
        this.origin = runtimeParams.parentOrigin;
        this.entityId = runtimeParams.entityId;
        this.entityMeta = runtimeParams.entityMeta;
        this.contextLevel = runtimeParams.contextLevel;
        this.innerUrl = runtimeParams.innerUrl;
        this.queryParams = runtimeParams.queryParams;
    }
}

export const hostApi = new HostApi();
