/** Код ошибки: не переданы обязательные параметры инициализации плагина (pluginId или slot). */
export const PLUGIN_ID_OR_SLOT_NOT_PROVIDED = 1000;

/** Код ошибки: переданный pluginId не совпадает с зарегистрированным плагином или неверного формата. */
export const PLUGIN_ID_IS_NOT_CORRECT = 1001;

/** Код ошибки: данные запроса не прошли валидацию (неверный формат, обязательные поля отсутствуют и т.п.). */
export const VALIDATION_ERROR = 1002;

/** Код ошибки: запрошенный метод API не поддерживается в данной конфигурации или версии. */
export const METHOD_NOT_SUPPORTED = 1003;

/** Код ошибки: у плагина нет необходимого scope (разрешения) для выполнения операции. */
export const MISSING_REQUIRED_SCOPE = 1004;

/** Код ошибки: ошибка получения или разбора контекста слота. */
export const CONTEXT_ERROR = 1005;

/** Код ошибки: вызов приватного RPC запрещён (только для экспериментов). */
export const PLUGIN_PRIVATE_RPC_FORBIDDEN = 1006;

/** Код ошибки: превышен лимит запросов (rate limit). */
export const RATE_LIMIT_EXCEEDED = 1007;

/** Код ошибки: диалог подтверждения уже открыт. */
export const CONFIRM_ALREADY_OPEN = 1008;

/** Код ошибки: очередь сообщений переполнена. */
export const QUEUE_OVERFLOW = 1009;

/** Код ошибки: версия записи в хранилище не совпадает с текущей (конфликт при обновлении). */
export const VERSION_CONFLICT = 1010;

/** Код ошибки: размер данных превышает 256 КиБ после выполнения операции. */
export const DATA_TOO_LARGE = 1011;

/** Код ошибки: ключ bucket не прошёл валидацию (неверный формат или длина). */
export const BAD_KEY = 1012;

/** Код ошибки: вызов внешнего API завершился ошибкой. */
export const EXTERNAL_API_CALL_ERROR = 1013;

/** Код ошибки: непредвиденная или неклассифицированная ошибка. */
export const UNKNOWN_ERROR = 6666;
