import { sendRequest } from '../bridge/bridge';
import { on } from '../events/eventBus';

export type ToastAction = {
    label: string;
    onClick: () => void;
};

export type ToastOptions = {
    name?: string;
    title: string;
    content?: string;
    theme?: 'success' | 'danger' | 'warning' | 'info';
    autoHiding?: number;
    isClosable?: boolean;
    actions?: ToastAction[];
};

export class Toaster {
    private callbackMap = new Map<string, () => void>();
    private toastActionIds = new Map<string, string[]>();
    private eventSubscribed = false;

    async add(options: ToastOptions): Promise<{ name: string }> {
        this.ensureEventSubscription();

        const actionIds: string[] = [];
        const serializedActions = options.actions?.map((action) => {
            const actionId = crypto.randomUUID();

            this.callbackMap.set(actionId, action.onClick);
            actionIds.push(actionId);

            return { id: actionId, label: action.label };
        });

        const result = (await sendRequest('toast.add', {
            name: options.name,
            title: options.title,
            content: options.content,
            theme: options.theme,
            autoHiding: options.autoHiding,
            isClosable: options.isClosable,
            actions: serializedActions,
        })) as { name: string };

        if (actionIds.length > 0) {
            this.toastActionIds.set(result.name, actionIds);
        }

        const autoHiding = options.autoHiding ?? 5000;

        setTimeout(() => this.cleanupCallbacksForToast(result.name), autoHiding + 1000);

        return result;
    }

    private ensureEventSubscription() {
        if (this.eventSubscribed) return;
        this.eventSubscribed = true;

        on('toast.action.clicked', ({ name, actionId }) => {
            const callback = this.callbackMap.get(actionId);

            // eslint-disable-next-line callback-return -- optional void callback for side effects
            callback?.();
            this.cleanupCallbacksForToast(name);
        });
    }

    private cleanupCallbacksForToast(name: string) {
        const actionIds = this.toastActionIds.get(name);

        if (actionIds) {
            for (const id of actionIds) {
                this.callbackMap.delete(id);
            }
            this.toastActionIds.delete(name);
        }
    }
}
