import {
    array,
    boolean,
    maxLength,
    maxValue,
    minValue,
    number,
    object,
    optional,
    picklist,
    pipe,
    string,
} from 'valibot';

export const confirmShowPayloadSchema = object({
    title: optional(
        pipe(string('Title must be a string'), maxLength(200, 'Title max length is 200')),
    ),
    message: pipe(string('Message is required'), maxLength(500, 'Message max length is 500')),
    textButtonApply: optional(
        pipe(
            string('textButtonApply must be a string'),
            maxLength(50, 'textButtonApply max length is 50'),
        ),
    ),
    textButtonCancel: optional(
        pipe(
            string('textButtonCancel must be a string'),
            maxLength(50, 'textButtonCancel max length is 50'),
        ),
    ),
    theme: optional(picklist(['normal', 'danger'])),
});

const toastActionSchema = object({
    id: string('Action id is required'),
    label: pipe(string('Action label is required'), maxLength(50, 'Action label max length is 50')),
});

export const toastAddPayloadSchema = object({
    name: optional(string()),
    title: pipe(string('Title is required'), maxLength(200, 'Title max length is 200')),
    content: optional(
        pipe(string('Content must be a string'), maxLength(500, 'Content max length is 500')),
    ),
    theme: optional(picklist(['success', 'danger', 'warning', 'info'])),
    autoHiding: optional(
        pipe(
            number('autoHiding must be a number'),
            minValue(1000, 'autoHiding minimum is 1000ms'),
            maxValue(30_000, 'autoHiding maximum is 30000ms'),
        ),
    ),
    isClosable: optional(boolean()),
    actions: optional(pipe(array(toastActionSchema), maxLength(2, 'Maximum 2 actions allowed'))),
});
