import type { GenericSchema } from 'valibot';
import { array, minLength, object, pipe } from 'valibot';

import { externalApiDomainInfoSchema } from './ExternalApiDomainInfoSchema';
import { ExternalApiDomainInfo } from './ExternalApiDomainInfo';

export type ExternalApiAuthRequestPayload = {
    domains: ExternalApiDomainInfo[];
};

export const externalApiAuthRequestPayloadSchema: GenericSchema<ExternalApiAuthRequestPayload> =
    object({
        domains: pipe(array(externalApiDomainInfoSchema), minLength(1)),
    });
