import type { ContentSizeUpdateRequest } from './ContentSizeUpdateRequest';
import { custom, number, object, optional, picklist, pipe } from 'valibot';

const baseContentSizeUpdateRequestSchema = object({
    height: optional(number('Height must be a number')),
    width: optional(number('Width must be a number')),
    unit: optional(picklist(['pixel', 'percent'], 'Unit must be either "pixel" or "percent"')),
});

export const contentSizeUpdateRequestSchema = pipe(
    baseContentSizeUpdateRequestSchema,
    custom<ContentSizeUpdateRequest>((input) => {
        const { height, width } = input as ContentSizeUpdateRequest;
        const hasHeight = height !== undefined;
        const hasWidth = width !== undefined;

        return hasHeight || hasWidth;
    }, 'At least one of height or width must be provided'),
);
