import { dispatchHostEvent } from '../events/eventBus';
import type { EventMessage } from '../events/types';
import { getHandler } from '../handlers/handlers';
import type { BaseMessage } from './types/BaseMessage';
import { UNKNOWN_ERROR } from './types/ErrorCodes';
import { PluginActionError } from './types/PluginActionError';

const BRIDGE_DESTROYED_ERROR = 'Bridge destroyed before response';

type RequestOptions = { timeout?: number };

type PendingRequest = {
    resolve: (value: unknown) => void;
    reject: (error: Error) => void;
    timeoutId: ReturnType<typeof setTimeout>;
};

type RawRequestMessage = BaseMessage & {
    method: string;
    payload: unknown;
};

type RawResponseMessage = BaseMessage & {
    type: 'response';
    result: unknown;
    error?: string;
    errorCode?: number;
    errorData?: unknown;
};

type RawIncomingRequestMessage = BaseMessage & {
    type: 'request';
    result: { method: string; payload: unknown };
    error?: string;
};

type IncomingEnvelope = Partial<BaseMessage> & {
    pluginId?: string;
    elementId?: string;
    type?: string;
    method?: string;
    result?: unknown;
};

class PluginBridge {
    private pluginId: string;
    private elementId: string;
    private targetOrigin: string;
    private slot: string;
    private entityId: string | null;
    private entityMeta: Record<string, string> | undefined;
    private pendingRequests: Map<string, PendingRequest> = new Map();
    private messageListener: ((event: MessageEvent) => void) | null = null;
    private readonly requestTimeout = 60000;

    constructor(
        pluginId: string,
        elementId: string,
        slot: string,
        entityId: string | null,
        targetOrigin: string,
        entityMeta?: Record<string, string>,
    ) {
        this.pluginId = pluginId;
        this.elementId = elementId;
        this.targetOrigin = targetOrigin;
        this.entityId = entityId;
        this.entityMeta = entityMeta;
        this.slot = slot;
        this.initListener();
    }

    request(method: string, payload?: unknown, options?: RequestOptions): Promise<unknown> {
        return new Promise((resolve, reject) => {
            const messageId = this.generateMessageId();
            const timeoutMs = options?.timeout ?? this.requestTimeout;

            const requestMessage: RawRequestMessage = {
                messageId,
                method,
                payload,
            };

            const timeoutId = setTimeout(() => {
                const pending = this.pendingRequests.get(messageId);
                if (pending) {
                    this.pendingRequests.delete(messageId);
                    reject(new Error(`Request timeout: ${method} exceeded ${timeoutMs}ms`));
                }
            }, timeoutMs);

            this.pendingRequests.set(messageId, { resolve, reject, timeoutId });

            try {
                this.send(requestMessage);
            } catch (e) {
                clearTimeout(timeoutId);
                this.pendingRequests.delete(messageId);
                reject(e as Error);
            }
        });
    }

    send<T = unknown>(message: T): void {
        window.parent.postMessage(
            {
                pluginId: this.pluginId,
                elementId: this.elementId,
                slot: this.slot,
                entityId: this.entityId,
                entityMeta: this.entityMeta,
                ...message,
            },
            this.targetOrigin,
        );
    }

    destroy(): void {
        if (this.messageListener) {
            window.removeEventListener('message', this.messageListener);
            this.messageListener = null;
        }

        this.pendingRequests.forEach((pending) => {
            clearTimeout(pending.timeoutId);
            pending.reject(new Error(BRIDGE_DESTROYED_ERROR));
        });
        this.pendingRequests.clear();
    }

    private initListener(): void {
        this.messageListener = async (event: MessageEvent) => {
            if (event.origin !== this.targetOrigin) {
                console.info(
                    '[Bridge] Ignored message from origin:',
                    event.origin,
                    '(expected:',
                    this.targetOrigin,
                    ')',
                );
                return;
            }

            const message = event.data;
            console.info('[Bridge] Received message:', message);

            if (!this.isExpectedSource(event) || !this.isMessageForCurrentPlugin(message)) {
                console.info('[Bridge] Ignored message for another plugin instance:', message);
                return;
            }

            if (message.type === 'event') {
                console.info('[Bridge] Dispatching host event:', message.method, message.result);
                dispatchHostEvent(message as EventMessage);
                return;
            }

            console.info('[Bridge] Received message:', event.data);

            if (!message.messageId) {
                console.info('[Bridge] Ignored message without messageId:', message);
                return;
            }

            const typedMessage = message as RawResponseMessage | RawIncomingRequestMessage;
            const pending = this.pendingRequests.get(typedMessage.messageId);

            if (!pending) {
                if (typedMessage.type === 'request') {
                    const incoming = typedMessage as RawIncomingRequestMessage;
                    const method = incoming.result.method;
                    const handler = getHandler(method);

                    if (!handler) {
                        this.send({
                            messageId: typedMessage.messageId,
                            type: 'response',
                            result: null,
                            errorCode: UNKNOWN_ERROR,
                            error: `No handler for method ${method}`,
                        });
                        return;
                    }

                    try {
                        const data = handler();
                        this.send({
                            messageId: typedMessage.messageId,
                            payload: data,
                            method: 'responseData',
                            type: 'response',
                        });
                    } catch (e) {
                        const err = e instanceof Error ? e : new Error(String(e));
                        const errorCode =
                            err instanceof PluginActionError ? err.code : UNKNOWN_ERROR;
                        this.send({
                            messageId: typedMessage.messageId,
                            type: 'response',
                            result: null,
                            errorCode,
                            error: err.message,
                        });
                    }
                }

                return;
            }

            clearTimeout(pending.timeoutId);
            this.pendingRequests.delete(typedMessage.messageId);

            const response = typedMessage as RawResponseMessage;
            if (response.type === 'response' && response.errorCode) {
                pending.reject(
                    new PluginActionError(
                        response.errorCode,
                        response.error ?? 'Unknown error',
                        response.errorData,
                    ),
                );
            } else {
                pending.resolve(response.result);
            }
        };

        window.addEventListener('message', this.messageListener);
    }

    private isExpectedSource(event: MessageEvent): boolean {
        return event.source === null || event.source === window.parent;
    }

    private isMessageForCurrentPlugin(message: unknown): message is IncomingEnvelope {
        if (typeof message !== 'object' || message === null) {
            return false;
        }

        const envelope = message as IncomingEnvelope;
        return (
            (envelope.pluginId === undefined || envelope.pluginId === this.pluginId) &&
            (envelope.elementId === undefined || envelope.elementId === this.elementId)
        );
    }

    private generateMessageId(): string {
        return crypto.randomUUID();
    }
}

let bridgeInstance: PluginBridge | null = null;

export function initBridge(
    pluginId: string,
    elementId: string,
    slot: string,
    entityId: string | null,
    targetOrigin: string,
    entityMeta?: Record<string, string>,
): PluginBridge {
    if (bridgeInstance) {
        bridgeInstance.destroy();
    }
    bridgeInstance = new PluginBridge(
        pluginId,
        elementId,
        slot,
        entityId,
        targetOrigin,
        entityMeta,
    );
    return bridgeInstance;
}

export function destroyBridge(): void {
    bridgeInstance?.destroy();
    bridgeInstance = null;
}

function getBridge(): PluginBridge {
    if (!bridgeInstance) {
        throw new Error('Bridge not initialized. Call initBridge first.');
    }
    return bridgeInstance;
}

export function sendRequest<TResult = unknown>(
    method: string,
    payload?: unknown,
    options?: RequestOptions,
): Promise<TResult> {
    return getBridge().request(method, payload, options) as Promise<TResult>;
}
