import { sendRequest } from '../bridge/bridge';
import { VERSION_CONFLICT } from '../bridge/types/ErrorCodes';

import type { StorageRecord } from './types';

export type StorageData = Record<string, unknown>;

export type PatchOptions = {
    bucket?: string;
    data: StorageData;
    version?: number;
};

const CONTEXT_TYPE = 'orgShared' as const;
const MAX_RETRIES = 2;

async function readRecord(bucket: string | undefined): Promise<StorageRecord | null> {
    const result = await sendRequest('storage.get', { contextType: CONTEXT_TYPE, bucket });

    return result as StorageRecord | null;
}

async function patchRecord(
    bucket: string | undefined,
    data: StorageData,
    version: number,
): Promise<StorageRecord> {
    const result = await sendRequest('storage.patch', {
        contextType: CONTEXT_TYPE,
        bucket,
        data,
        version,
    });

    return result as StorageRecord;
}

function isVersionConflict(err: unknown): boolean {
    return (
        typeof err === 'object' &&
        err !== null &&
        (err as { code?: unknown }).code === VERSION_CONFLICT
    );
}

function orgSharedGet(bucket?: string): Promise<StorageRecord | null> {
    return readRecord(bucket);
}

async function orgSharedPatch({ bucket, data, version }: PatchOptions): Promise<StorageRecord> {
    if (version !== undefined) {
        return patchRecord(bucket, data, version);
    }

    let lastError: unknown;

    for (let attempt = 0; attempt <= MAX_RETRIES; attempt += 1) {
        const currentVersion = (await readRecord(bucket))?.version ?? 0;

        try {
            return await patchRecord(bucket, data, currentVersion);
        } catch (err) {
            if (!isVersionConflict(err)) throw err;
            lastError = err;

            if (attempt < MAX_RETRIES) {
                console.warn(
                    `[storageApi] orgShared.patch: VERSION_CONFLICT on version ${currentVersion}, retry ${attempt + 1}/${MAX_RETRIES}`,
                );
            }
        }
    }

    throw lastError;
}

export const storageApi = {
    orgShared: {
        get: orgSharedGet,
        patch: orgSharedPatch,
    },
};
