type AnyHandler = (...args: unknown[]) => unknown;

const handlers: Record<string, AnyHandler> = {};

/**
 * Регистрирует handler по имени. Тип не проверяется на runtime'е;
 * type-safety обеспечивается typed wrapper'ом в публикуемых пакетах.
 */
export function setHandler(name: string, handler: AnyHandler): void {
    handlers[name] = handler;
}

/**
 * Возвращает зарегистрированный handler по имени, или undefined.
 */
export function getHandler(name: string): AnyHandler | undefined {
    return handlers[name];
}
