import {
    integer,
    maxLength,
    minLength,
    minValue,
    number,
    object,
    optional,
    picklist,
    pipe,
    record,
    regex,
    string,
    unknown,
} from 'valibot';

const bucketSchema = optional(
    pipe(
        string('bucket must be a string'),
        minLength(1, 'bucket must not be empty'),
        maxLength(64, 'bucket max length is 64'),
        regex(/^[\w.-]+$/, 'bucket allows only A-Z, a-z, 0-9, dot, underscore, hyphen'),
    ),
);

const versionSchema = pipe(
    number('version must be a number'),
    integer('version must be an integer'),
    minValue(0, 'version must be >= 0'),
);

const contextTypeSchema = picklist(['orgShared'], 'contextType must be "orgShared"');

export const storageGetPayloadSchema = object({
    contextType: contextTypeSchema,
    bucket: bucketSchema,
});

export const storagePatchPayloadSchema = object({
    contextType: contextTypeSchema,
    bucket: bucketSchema,
    data: record(string(), unknown()),
    version: versionSchema,
});
